with incoming(lemma, kind, sense_id, ordinal, pos, gender, text, example, example_translation) as (values ('holde fast', 'phrase', '8b1604ec-0305-5ce6-bdd4-7fccd3f03707', 1, 'verb', null, 'to stick to (an opinion, decision)', 'Hun holder fast i sin mening om filmen.', 'She sticks to her opinion about the film.'), ('stå fast', 'phrase', '6e755c97-d15d-556f-8620-9f17f83bf935', 1, 'verb', null, 'to stand firm', 'Hun står fast på sin beslutning.', 'She stands firm on her decision.'), ('være tæt på', 'phrase', '12a302d2-df21-5dd6-9486-2fb102d1d518', 1, 'verb', null, 'to be close to (sth.)', 'Huset er tæt på skoven.', 'The house is close to the forest.'), ('være tæt på', 'phrase', 'de0659cd-14a6-5cdd-a4a4-caf467412779', 2, 'verb', null, 'to nearly (do sth.)', 'Jeg var tæt på at græde.', 'I was close to crying.'), ('føle med', 'phrase', 'd0346ab3-6c83-5607-998a-13c820fca439', 1, 'verb', null, 'to sympathise', 'Jeg føler med dig i den svære tid.', 'I feel for you during this difficult time.'), ('hjælpe mod', 'phrase', 'b1f859c0-38a5-5723-993c-740c7847d135', 1, 'verb', null, 'to help against (pain, illness)', 'Den her medicin hjælper mod min hovedpine.', 'This medicine helps against my headache.'), ('flytte tilbage', 'phrase', '6f925739-4f43-59b4-8fe9-72904d377a6d', 1, 'verb', null, 'to move back', 'De flyttede tilbage til København sidste år.', 'They moved back to Copenhagen last year.'), ('ændre på', 'phrase', 'd6ea7d3f-0db2-53ba-ad26-1ac3ea71487b', 1, 'verb', null, 'to change (something)', 'Jeg vil gerne ændre på aftalen.', 'I would like to change the agreement.'), ('holde sig væk', 'phrase', '246d28ce-8e43-5d18-8f2d-78aea0941e42', 1, 'verb', null, 'to stay away (not approach)', 'Du skal holde dig væk fra den gamle bygning.', 'You need to stay away from the old building.'), ('gå i krig', 'phrase', 'c559bf10-ecad-5249-a561-df3361261a48', 1, 'verb', null, 'to go to war', 'Landet gik i krig efter mange års fred.', 'The country went to war after many years of peace.'), ('falde fra hinanden', 'phrase', '6091d01d-e695-549d-9e67-6e9052c1965b', 1, 'verb', null, 'to fall apart (object)', 'Den gamle stol falder fra hinanden, når du sætter dig på den.', 'The old chair falls apart when you sit on it.'), ('søge hjælp', 'phrase', '33053f31-1e24-5b43-893a-b2018575c70f', 1, 'verb', null, 'to seek help', 'Hun søger hjælp hos sin læge.', 'She seeks help from her doctor.'), ('svare ja', 'phrase', '5475b414-11fe-510d-81d5-6f0c22b7d606', 1, 'verb', null, 'to answer yes', 'Hun svarede ja til invitationen med det samme.', 'She said yes to the invitation immediately.'), ('gå sig en tur', 'phrase', '118bd8d6-564a-5a31-bd99-d2b04108098b', 1, 'verb', null, 'to go for a walk', 'Jeg går mig en tur hver aften efter aftensmad.', 'I go for a walk every evening after dinner.'), ('mene det alvorligt', 'phrase', '8273e68f-2069-56bf-8e68-f049e52dee5d', 1, 'verb', null, 'to mean it seriously', 'Jeg mener det alvorligt, når jeg siger, at jeg flytter.', 'I am serious when I say that I am moving.'), ('være i tvivl', 'phrase', 'faaaaf35-adca-5299-801a-466a32f7d44e', 1, 'verb', null, 'to be in doubt', 'Jeg er i tvivl om svaret er rigtigt.', 'I am in doubt whether the answer is correct.'), ('stemme imod', 'phrase', 'c3b285df-7599-5cee-b3d7-c777b4db658e', 1, 'verb', null, 'to vote against', 'De fleste i udvalget stemte imod forslaget.', 'The majority of the committee voted against the proposal.'), ('skifte fra', 'phrase', 'ff0aaa8e-d2b0-59a2-9629-44206b7dcfc0', 1, 'verb', null, 'to switch from', 'Jeg skifter fra kaffe til te om aftenen.', 'I switch from coffee to tea in the evening.'), ('kunne stå inde for', 'phrase', 'fe0709aa-0b2d-5b18-b728-a6b5aa9b72d5', 1, 'verb', null, 'to vouch for', 'Jeg kan stå inde for kvaliteten af maden her.', 'I can vouch for the quality of the food here.'), ('holde en pause', 'phrase', '902faf16-bf28-52fe-ac3b-bc68bc49eab0', 1, 'verb', null, 'to take a break', 'Jeg holder en pause fra arbejdet.', 'I''m taking a break from work.'), ('træde frem', 'phrase', '1d4fe771-7361-5272-b922-cf76ef23dc75', 1, 'verb', null, 'to step forward', 'Hun trådte frem fra mængden og smilede.', 'She stepped forward from the crowd and smiled.'), ('træde til', 'phrase', '5ffc86c8-1624-57f5-a7ca-6945a7d44df7', 1, 'verb', null, 'to step in, to intervene', 'Brandmanden trådte til da ilden spredte sig hurtigt.', 'The firefighter stepped in as the fire spread quickly.'), ('dreje af', 'phrase', '2e36f1e3-b6c2-50c7-ad36-ff91e4b5a773', 1, 'verb', null, 'to turn off', 'Bilen drejede af ved næste vej.', 'The car turned off at the next road.'), ('foretage sig', 'phrase', 'bd97badb-7f51-5684-b2bc-f17369d3bf76', 1, 'verb', null, 'to do (to occupy oneself)', 'Hvad vil du foretage dig i weekenden?', 'What do you want to do this weekend?'), ('slutte sig til', 'phrase', 'ec8b9733-28ff-5a9d-8e97-4c6f2669ac97', 1, 'verb', null, 'to join (a group or opinion)', 'Jeg slutter mig til holdet i morgen.', 'I''ll join the team tomorrow.'), ('slippe op', 'phrase', '88ce702d-64f2-58dc-aee3-39e8da176838', 1, 'verb', null, 'to run out (of supplies)', 'Mælken slap op i morges.', 'The milk ran out this morning.'), ('holde stand', 'phrase', 'a6d10047-4334-518c-b19b-56a6b0ef30f4', 1, 'verb', null, 'to hold one''s ground', 'Soldaterne holdt stand mod fjenden hele natten.', 'The soldiers held their ground against the enemy all night.'), ('dække over', 'phrase', '5c57d1e5-fee0-5cdd-98a7-eeeccf3bb577', 1, 'verb', null, 'to cover up', 'Hans smil dækkede over en stor usikkerhed.', 'His smile covered up a great deal of insecurity.'), ('dække over', 'phrase', 'f82cc88e-6a36-529b-ac78-6bcaf66491ba', 2, 'verb', null, 'to cover (include in meaning)', 'Ordet ''dyr'' dækker over mange forskellige arter.', 'The word ''animal'' covers many different species.'), ('ringe op', 'phrase', 'ab5a41f4-953d-5794-8784-098ec3d9fd9c', 1, 'verb', null, 'to call (on the phone)', 'Jeg ringer op til min ven i aften.', 'I''ll call my friend tonight.'), ('varme op', 'phrase', '6df1da05-a28a-58b1-9750-e89a097ad693', 1, 'verb', null, 'to warm up (before exercise)', 'Vi varmer op inden løbeturen.', 'We warm up before the run.'), ('spare op', 'phrase', '2a632b31-f911-5f93-8ba1-53c3a2c05922', 1, 'verb', null, 'to save up (money)', 'Hun sparer op til en ny cykel.', 'She is saving up for a new bike.'), ('spare på', 'phrase', 'fd031481-92d5-583c-aa80-474b617a3003', 1, 'verb', null, 'to save (use less of)', 'Vi sparer på vandet i tørkeperioder.', 'We save water during periods of drought.'), ('lave sjov', 'phrase', '93f0e368-e5aa-5939-8b06-2c38d6ac7c9f', 1, 'verb', null, 'to joke, to fool around', 'Børnene laver sjov i haven hele dagen.', 'The children are joking around in the garden all day.'), ('drive forretning', 'phrase', '3c56373d-1c91-5390-901a-b63a5219febe', 1, 'verb', null, 'to run a business', 'Han driver forretning fra sit hjem.', 'He runs a business from his home.'), ('træffe en beslutning', 'phrase', '03046b8c-a876-52bc-96dd-3a665db3f46c', 1, 'verb', null, 'to make a decision', 'Hun traf en beslutning om at flytte til byen.', 'She made a decision to move to the city.'), ('flyve med', 'phrase', '962c8bce-1fa4-581a-8249-c24c1a8360a8', 1, 'verb', null, 'to fly with (someone)', 'Jeg flyver med min søster til London i morgen.', 'I''m flying with my sister to London tomorrow.'), ('snakke færdig', 'phrase', '0a6a6e86-a442-53f7-ba2f-d100a53dbb79', 1, 'verb', null, 'to finish talking', 'Vi snakkede færdig før mødet startede.', 'We finished talking before the meeting started.'), ('brænde sig', 'phrase', '34f01c88-fadf-52a8-a600-86129c99fdce', 1, 'verb', null, 'to burn oneself', 'Pas på, du kan brænde dig på den varme pande.', 'Be careful, you can burn yourself on the hot pan.'), ('indgå fred', 'phrase', 'dd9357e4-1632-5cd1-95cb-f7467e0e9c86', 1, 'verb', null, 'to make peace', 'De to lande indgik fred efter krigen.', 'The two countries made peace after the war.'), ('ofre sig', 'phrase', 'a6b010cd-d920-5773-93f2-60feba98a4de', 1, 'verb', null, 'to sacrifice oneself', 'Hun ofrede sig for sin families skyld.', 'She sacrificed herself for the sake of her family.'), ('være i brand', 'phrase', '8759cb13-6aca-5d9b-8b6d-8b5f05480915', 1, 'verb', null, 'to be on fire', 'Bygningen er i brand, og brandvæsenet er på vej.', 'The building is on fire and the fire brigade is on the way.'), ('få bank', 'phrase', '0d220c1c-5916-50f8-a529-bc4212fb98e8', 1, 'verb', null, 'to get a beating', 'Han fik bank af de store drenge i skolegården.', 'He was beaten by the big boys in the schoolyard.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'en'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'en', text, pos, gender, example, example_translation, 'pipeline-phrases-0009' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
